nput asp-for="Criteria.AdmissionFrom" id="SRC-011" type="date"></label><label>入学日・終了<input asp-for="Criteria.AdmissionTo" id="SRC-012" type="date"></label></div><div class="actions"><button type="submit" class="primary">検索</button><button type="submit" formaction="/students/options">候補を更新</button></div></fieldset></form>
