1: using StudentManagement.Core;
2: namespace StudentManagement.Web;
3: public sealed class WebStudentCoordinator(IStudentService service,RequestIdentity identity,SearchContextStore contexts)
4: {
5:     public SearchContextStore.Entry NewContext(string? tab=null)=>contexts.Create(identity.CurrentUser,tab);
6:     public void CheckReturn(string? id) { if(!string.IsNullOrEmpty(id)) contexts.Get(id,identity.CurrentUser); }
7:     public async Task<object> Search(SearchRequest request,string? tab,CancellationToken ct) {
8:         identity.Read(); var criteria=request.Criteria.ToCriteria(request.PageSize,request.SortKey,request.SortDirection);
9:         return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result; entry.Revision++; return Present(entry,result); },ct);
10:     }
11:     public async Task<object> Page(PageRequest request,string? tab,CancellationToken ct) {
12:         identity.Read(); return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { if(entry.Applied is null) throw new WebFault(409,"先に検索してください。"); var criteria=SearchContextStore.Copy(entry.Applied); criteria.Page=criteria.PageSize!=request.PageSize||criteria.SortKey!=request.SortKey||criteria.SortDirection!=request.SortDirection?1:request.Page; criteria.PageSize=request.PageSize; criteria.SortKey=request.SortKey;criteria.SortDirection=request.SortDirection; var result=await service.SearchAsync(criteria,ct); EnsureSearch(result); if(!result.LimitExceeded&&criteria.Page>Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize)) { criteria.Page=Math.Max(1,(result.Count+criteria.PageSize-1)/criteria.PageSize);result=await service.SearchAsync(criteria,ct);EnsureSearch(result); } entry.Applied=SearchContextStore.Copy(criteria);entry.LastResult=result;entry.Revision++;return Present(entry,result); },ct);
13:     }
14:     public async Task<object> Resume(ContextRequest request,string? tab,CancellationToken ct) { identity.Read(); return await contexts.Use(request,identity.CurrentUser,tab,async entry=> { if(entry.Applied is null) return Present(entry,null); var result=await service.SearchAsync(entry.Applied,ct);EnsureSearch(result);entry.LastResult=result;entry.Revision++;return Present(entry,result); },ct); }
15:     public Task<object> Clear(ContextRequest request,string? tab,CancellationToken ct) { identity.Read(); return contexts.Use(request,identity.CurrentUser,tab,entry=> { entry.Applied=null;entry.LastResult=null;entry.Revision++;return Task.FromResult(Present(entry,null)); },ct); }
16:     public async Task<object> Options(OptionsRequest request,CancellationToken ct) { identity.Read(); if(request.Usage=="register") identity.CreateOrUpdate(); StudentDetail? existing=null; if(!string.IsNullOrEmpty(request.StudentId)) existing=await service.GetAsync(IdParser.Required(request.StudentId,"REG-INT-012"),ct) ?? throw new WebFault(404,"学生情報が見つかりません。",messageId:"E-STU-103"); return WebPresentation.Lookups(await service.LookupAsync(request.Usage=="register",ct),request.Usage,existing,request.SchoolYear,request.GradeCode,request.EnrollmentStatusCode,request.AdmissionDate,request.EnrollmentEndDate); }
17:     public async Task<(StudentDetail? Detail,StudentSaveInput Form,LookupSet Lookups)> Edit(long? id,string? contextId,CancellationToken ct) { identity.Read();CheckReturn(contextId); if(id is null) identity.CreateOrUpdate(); var detail=id is null?null:await service.GetAsync(id.Value,ct)??throw new WebFault(404,"学生情報が見つかりません。",messageId:"E-STU-103");var lookup=await service.LookupAsync(ct);return(detail,StudentSaveInput.From(detail,contextId,lookup),lookup); }
18:     public async Task<SaveResult> Save(long? id,StudentSaveInput input,CancellationToken ct) { identity.CreateOrUpdate();CheckReturn(input.ReturnContextId); return await service.SaveAsync(input.ToRequest(id),ct); }
19:     public async Task<SaveResult> Delete(long id,StudentDeleteInput input,CancellationToken ct) { identity.Administrator(); CheckReturn(input.ReturnContextId);if(!input.Confirmed) throw new WebFault(422,"削除対象と理由を確認してください。","REG-026");return await service.DeleteAsync(id,IdParser.Required(input.ExpectedVersion,"REG-INT-013"),input.Reason,ct); }
20:     private static void EnsureSearch(SearchResult result) { if(result.Outcome is not (Outcome.Saved or Outcome.NoChange)) { var error=result.Errors.FirstOrDefault();throw new WebFault(WebPresentation.Status(result.Outcome),error?.Message??"検索できませんでした。",error?.Field,error?.Code??"E-COM-004"); } }
21:     public static object Present(SearchContextStore.Entry entry,SearchResult? result) { var c=entry.Applied??new SearchCriteria(); return new { outcome=result is null?"unsearched":result.LimitExceeded?"tooMany":result.Count==0?"empty":"found",totalCount=result is null||result.LimitExceeded?(int?)null:result.Count,items=(result?.Items??[]).Select(WebPresentation.Row),page=c.Page,pageSize=c.PageSize,sortKey=c.SortKey,sortDirection=c.SortDirection,searchedAt=result is null?null:WebPresentation.Time(result.SearchedAt),contextId=entry.Id,contextRevision=entry.Revision.ToString(System.Globalization.CultureInfo.InvariantCulture),criteria=new { studentNo=c.StudentNo??"",name=c.StudentName??"",kana=c.StudentNameKana??"",c.SchoolYear,c.GradeCode,classId=c.ClassId?.ToString(System.Globalization.CultureInfo.InvariantCulture),c.UnassignedOnly,statusCodes=c.EnrollmentStatusCodes,c.PrefectureCode,phoneNumber=c.PhoneNumber??"",c.AdmissionFrom,c.AdmissionTo } }; }
22: }
