340:         Param(command,"@token",SqlDbType.UniqueIdentifier,id); Param(command,"@actor",SqlDbType.NVarChar,user.Principal,128); Param(command,"@session",SqlDbType.UniqueIdentifier,Guid.Parse(user.SessionId));
341:         Param(command,"@id",SqlDbType.BigInt,request.StudentId); Param(command,"@version",SqlDbType.BigInt,request.ExpectedVersion); Param(command,"@payload",SqlDbType.Binary,payload,32); Param(command,"@candidates",SqlDbType.Binary,candidates,32); Param(command,"@expires",SqlDbType.DateTimeOffset,now.AddMinutes(10));
