354:                 if(!reader.GetBoolean(0) || !reader.GetBoolean(1) || DateOnly.FromDateTime(reader.GetDateTime(2))>day || !reader.IsDBNull(3)&&DateOnly.FromDateTime(reader.GetDateTime(3))<day) errors.Add(new(StudentNormalizer.PropertyNames[column],"E-STU-011","コードは現在使用できません。"));
355:             }
356:         }
