358:         var oldStatus=(string?)previous?.GetValueOrDefault("enrollment_status_code");
359:         var status=student.Text("enrollment_status_code");
360:         var oldSeat=oldClass is not null && oldStatus is "01" or "02";
361:         var newSeat=student.ClassId is not null && status is "01" or "02";
362:         if(student.ClassId is { } classId) {
363:             await using var command=Command(connection,tx,"SELECT school_year,grade_code,valid_from,valid_to,is_active,capacity FROM dbo.m_class WHERE class_id=@id");
364:             Param(command,"@id",SqlDbType.BigInt,classId);
365:             int? capacity=null;
