367:                 if(!await reader.ReadAsync(ct)) errors.Add(new("ClassId","E-STU-010","指定クラスが存在しません。"));
368:                 else {
369:                     var start=DateOnly.FromDateTime(reader.GetDateTime(2)); var end=DateOnly.FromDateTime(reader.GetDateTime(3));
